select case when year(launch_date) < 2024 then 'before_2024' when year(launch_date) = 2024 then '2024' else 'after_2024' end as launch_cohort, round((100 * sum(case when category = 'Grocery' then 1 else 0 end)) / count(*), 1) as pct_grocery, sort_array(collect_set(brand)) as brand_list from products where supplier_id in (20, 36) and supplier_id is not null and category = 'Sports' group by case when year(launch_date) < 2024 then 'before_2024' when year(launch_date) = 2024 then '2024' else 'after_2024' end order by pct_grocery desc;
